// Backend bridge. Inside the Tauri app it calls the Rust commands; in a plain
// browser it falls back to a small in-memory demo keyboard so the UI can be previewed.
const api = (() => {
  const tauri = window.__TAURI__ && window.__TAURI__.core;
  if (tauri) {
    return { demo: false, call: (cmd, args) => tauri.invoke(cmd, args || {}) };
  }

  // ---- demo keyboard: a Node 75 LP factory map (8 layers, 6x16 + 5 extra) ----
  const ROWS = 6, COLS = 16, EXTRA = 5, LAYERS = 8, PER = 4, SLOTS = ROWS * COLS + EXTRA;
  const FACTORY =
    "00290069006a7e067e077e087e1600ac00ae00ab00a800aa00a97e0b0049004c0035001e001f00200021002200230024002500260027002d" +
    "002e002a0000004a002b0014001a000800150017001c0018000c00120013002f003000310000004d00390004001600070009000a000b000d" +
    "000e000f00330034000000280000004b00e1001d001b00060019000500110010003600370038000000e500520000004e00e000e200e30000" +
    "0000002c00000000000000e7522100e4005000510000004f7e1b00a800ab00aa00a90001003a003b003c003d003e003f0040004100420043" +
    "004400457e0a0001000100017e037e047e057e02000100010001000100010001000100017e47000000017e18000100010001000100010001" +
    "0001000100017e3b7e137e147e15000000010001000100010001000100010001000100010001000100010000000100000001000100015223" +
    "7e190001000100015222782a7829000100000001782700000001000100010001000000000001000000000000000100015221782178280000" +
    "78237e1b00a800ab0069006a00010001000100010001000100010001000100010001000100017e3f00010001000100010001000100010001" +
    "0001000100010001000100010001000100000001000100010001000100010001000100010001000100010001000100010000000100010001" +
    "00017e27000100010001000100010001000100010000000100000001000100010001000100010001000100017e127e117e3c000000017e0d" +
    "000000010001000100010000000000010000000000000001000152227e0f7e0e00007e107e1b00a800ab7828782700010001000100010001" +
    "0001000100010001000100010001000100010001000100010001000100010001000100010001000100010001000100010001000000010001" +
    "000100017e4400010001000100010001000100010001000100010000000100010001000100017e3d00017e53000100010001000100010000" +
    "0001000000010001000100010001000100010001000100010001000100000001004b00000001000100010001000000007e54000000000000" +
    "000100010001004a004e0000004d7e1b00a800ab00aa00a90029003a003b003c003d003e003f0040004100420043004400457e0b0049004c" +
    "0035001e001f00200021002200230024002500260027002d002e002a0000004a002b0014001a000800150017001c0018000c00120013002f" +
    "003000310000004d00390004001600070009000a000b000d000e000f00330034000000280000004b00e1001d001b00060019000500110010" +
    "003600370038000000e500520000004e00e000e300e200000000002c00000000000000e6522500e4005000510000004f7e1b00a800ab00aa" +
    "00a9000100be00bd003c003d003e003f00ac00ae00ab00a800aa00a97e0a0001000100017e037e047e057e02000100010001000100010001" +
    "000100017e47000000017e180001000100010001000100010001000100017e3b7e137e147e15000000010001000100010001000100010001" +
    "0001000100010001000100000001000000010001000152277e19000100017e575226782a7829000100000001782700000001000100010001" +
    "00000000000100000000000000010001522578217828000078237e1b00a800ab00be00bd0001000100010001000100010001000100010001" +
    "0001000100010001000100010001000100010001000100010001000100010001000100010001000100000001000100010001000100010001" +
    "00010001000100010001000100010001000000010001000100017e2700010001000100010001000100010001000000010000000100010001" +
    "0001000100010001000100017e127e117e3c000000017e0d000000010001000100010000000000010000000000000001000152227e0f7e0e" +
    "00007e107e1b00a800ab78287827000100010001000100010001000100010001000100010001000100010001000100010001000100010001" +
    "000100010001000100010001000100010001000000010001000100017e440001000100010001000100010001000100010001000000010001" +
    "0001000100017e3d00017e530001000100010001000100000001000000010001000100010001000100010001000100010001000100000001" +
    "004b00000001000100010001000000007e54000000000000000100010001004a004e0000004d7e1b00a800ab00aa00a9";
  const defaults = [];
  for (let i = 0; i < FACTORY.length; i += 4) defaults.push(parseInt(FACTORY.slice(i, i + 4), 16));
  const NAMES = { no: 0, trns: 1, esc: 0x29, caps: 0x39, pscr: 0x46, ins: 0x49, del: 0x4c, home: 0x4a, end: 0x4d,
    pgup: 0x4b, pgdn: 0x4e, lgui: 0xe3, mute: 0xa8, vold: 0xaa, volu: 0xa9, mply: 0xae, mnxt: 0xab };
  const label = c => (typeof Keys !== "undefined" ? Keys.text(c, false) : "0x" + c.toString(16));
  let keys = defaults.slice();
  keys[4 * SLOTS + 13] = NAMES.lgui; // like the real keyboard once had: PrtSc position set to Win
  let backups = [];
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const dto = () => ({
    path: "/dev/hidraw6 (demo)", name: "NuPhy Node 75 LP (demo)", model: "Node75", vid: 0x19f5, pid: 0x1030,
    firmware: "1.0.10.6", current_mode: 1, layer_count: LAYERS, layers_per_mode: PER, rows: ROWS, cols: COLS, extra: EXTRA,
    active_layer: 4, slots_per_layer: SLOTS, keys: keys.map(c => ({ code: c, label: label(c) })), defaults: defaults.slice()
  });
  const parse = text => {
    const t = text.trim();
    if (!t) throw { code: "bad_key", detail: "empty" };
    if (/^0x[0-9a-f]{1,4}$/i.test(t)) { const c = parseInt(t, 16); return { code: c, label: label(c) }; }
    if (t.toLowerCase() in NAMES) { const c = NAMES[t.toLowerCase()]; return { code: c, label: label(c) }; }
    throw { code: "bad_key", detail: "unknown key '" + t + "'" };
  };
  const handlers = {
    async connect() { await sleep(250); return dto(); },
    async disconnect() {}, async refresh() { return dto(); },
    async parse_key({ text }) { return parse(text); },
    async set_key({ layer, slot, text }) { const k = parse(text); backups.unshift(Date.now()); keys[layer * SLOTS + slot] = k.code; return k; },
    async reset_key({ layer, slot }) { const c = defaults[layer * SLOTS + slot]; backups.unshift(Date.now()); keys[layer * SLOTS + slot] = c; return { code: c, label: label(c) }; },
    async list_backups() { return backups.map(t => ({ path: "demo-" + t, name: "1030-" + t + ".bin", time_ms: t })); },
    async make_backup() { backups.unshift(Date.now()); return "demo"; },
    async restore_backup() { return dto(); }
  };
  return { demo: true, call: (cmd, args) => handlers[cmd](args || {}) };
})();
